import{_ as i,o as l,c as o,aw as c}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Blockchain","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/common2/blockchain/blockchain/blockchain.md","filePath":"wiki/dev-commit/common2/blockchain/blockchain/blockchain.md"}'),e={name:"wiki/dev-commit/common2/blockchain/blockchain/blockchain.md"};function t(n,a,r,h,s,k){return l(),o("div",null,[...a[0]||(a[0]=[c('<h1 id="blockchain" tabindex="-1">Blockchain <a class="header-anchor" href="#blockchain" aria-label="Permalink to &quot;Blockchain&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://www.youtube.com/watch?v=UkAhVpiUVd4" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=UkAhVpiUVd4</a></p></div><h3 id="структура-блока" tabindex="-1">Структура блока <a class="header-anchor" href="#структура-блока" aria-label="Permalink to &quot;Структура блока&quot;">​</a></h3><p><strong>Blockchain</strong> - цепочка блоков, которые содержат информацию:</p><ol><li>Данные. Зависит от типа Blockchain, н-р для Bitcoin: отправитель, получатель, сумма</li><li>Хэш блока. Если в блоке есть изменения, то меняется хэш блока, что делает недействительным все последующие блоки (каждый последующий блок хранит хэш предыдущего)</li><li>Хэш предыдущего блока. Если нет предыдущего блока, то это первый блок (Генезис-блок)</li></ol><h3 id="децентрализация" tabindex="-1">Децентрализация <a class="header-anchor" href="#децентрализация" aria-label="Permalink to &quot;Децентрализация&quot;">​</a></h3><ul><li>Использование одноранговой сети</li><li>Децентрализованный глобальный код, открытый для всех</li></ul><p><strong>P2P</strong> (Peer-to-Peer). Blockchain использует P2P сеть и любой человек может присоединиться</p><ul><li>При подключении к сети, пользователь получает полную копию Blockchain</li><li>При создании нового блока, он отправляется всем подключенным к сети узлам (пользователям). Каждый узел проверяет новый блок и его хэш, чтобы убедиться в его достоверности. Если всё в порядке, то каждый узел добавляет это блок в свою копию Blockchain. Если блок фальсифицирован, то будет отклонен остальными узлами сети</li><li>Чтобы фальсифицировать блок, то под контролем должно быть более 50% сейти Blockchain, чтобы признать консенсус и признать фальсифициорованный блок действительным, поэтоум однажды записанную информация практически невозможно изменить или удалить</li></ul><h3 id="принципы-безопасности" tabindex="-1">Принципы безопасности <a class="header-anchor" href="#принципы-безопасности" aria-label="Permalink to &quot;Принципы безопасности&quot;">​</a></h3><ol><li>Хэширование - задание уникального хэша каждому блоку. Блок хранит свой хэш и хэш последующего блока</li><li>Prof of Work - механизм, замедляющий создание новых блоков (для Bitcoin это 10 минут). Существенно затрудняется изменение блоков: если изменяется 1 блок, то нужно пересчитать Prof of Work для всех остальных блоков, что является труным процессом</li><li>Децентрализация</li></ol><h3 id="создание-нового-блока" tabindex="-1">Создание нового блока <a class="header-anchor" href="#создание-нового-блока" aria-label="Permalink to &quot;Создание нового блока&quot;">​</a></h3><ul><li>Эмиссия осуществляется за счёт майнинга</li><li>Устройство, которые быстрее всех решит криптографическую задачу и создаст новый блок, получит немного криптовалюты</li></ul><h3 id="правила" tabindex="-1">Правила <a class="header-anchor" href="#правила" aria-label="Permalink to &quot;Правила&quot;">​</a></h3><ul><li>У каждой криптовалюты должен быть свой Blockchain</li></ul>',15)])])}const u=i(e,[["render",t]]);export{m as __pageData,u as default};
